"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["60203"],{779297(n){n.exports=JSON.parse('{"id":12048,"title":"\u8BAD\u7EC3\u8FC7\u7A0B","description":"\u8BF7\u8BA4\u771F\u9605\u8BFB\u6211\u63D0\u4F9B\u7684\u6587\u7AE0/\u8BBA\u6587\u5168\u6587\uFF0C\u91CD\u70B9\u5206\u6790\u6A21\u578B\u7684\u8BAD\u7EC3\u8FC7\u7A0B\uFF0C\u5C3D\u91CF\u628A\u4F5C\u8005\u201C\u600E\u4E48\u628A\u8FD9\u4E2A\u6A21\u578B\u8BAD\u7EC3\u51FA\u6765\u7684\u201D\u8BB2\u6E05\u695A\u3002\u8BF7\u7528\u4E2D\u6587\u56DE\u7B54\uFF0C\u8BED\u8A00\u901A\u4FD7\u3001\u6E05\u6670\u3001\u6709\u903B\u8F91\uFF0C\u9002\u5408\u521D\u5B66\u8005\u7406\u89E3\u3002\u4E0D\u8981\u53EA\u7FFB\u8BD1\u539F\u6587\uFF0C\u8981\u91CD\u65B0\u7EC4\u7EC7\u5185\u5BB9\u3002\\n\\n\u8BF7\u56F4\u7ED5\u4E0B\u9762\u8FD9\u4E9B\u95EE\u9898\u5C55\u5F00\uFF0C\u5C24\u5176\u8981\u91CD\u70B9\u56DE\u7B54\u8BAD\u7EC3\u76F8\u5173\u5185\u5BB9\uFF1A\\n\\n1. \u8FD9\u7BC7\u6587\u7AE0\u5230\u5E95\u8BAD\u7EC3\u4E86\u4EC0\u4E48\u6A21\u578B\uFF1F\\n\u6A21\u578B\u540D\u79F0\u662F\u4EC0\u4E48\uFF1F\\n\u8FD9\u662F\u4F5C\u8005\u81EA\u5DF1\u63D0\u51FA\u7684\u65B0\u6A21\u578B\uFF0C\u8FD8\u662F\u57FA\u4E8E\u5DF2\u6709\u6A21\u578B\u6539\u8FDB\u7684\uFF1F\\n\u8FD9\u662F\u5927\u6A21\u578B\u3001\u5C0F\u6A21\u578B\uFF0C\u8FD8\u662F\u67D0\u4E2A\u9884\u8BAD\u7EC3\u6A21\u578B\u7684\u4E0B\u6E38\u7248\u672C\uFF1F\\n\u6A21\u578B\u4E3B\u8981\u7528\u4E8E\u5B8C\u6210\u4EC0\u4E48\u4EFB\u52A1\uFF1F\\n2. \u6A21\u578B\u7684\u8BAD\u7EC3\u76EE\u6807\u662F\u4EC0\u4E48\uFF1F\\n\\n\u8BF7\u660E\u786E\u8BF4\u660E\uFF1A\\n\\n\u8BAD\u7EC3\u8FD9\u4E2A\u6A21\u578B\u662F\u4E3A\u4E86\u505A\u4EC0\u4E48\uFF1F\\n\u4F8B\u5982\u5206\u7C7B\u3001\u9884\u6D4B\u3001\u751F\u6210\u3001\u68C0\u6D4B\u3001\u51B3\u7B56\u3001\u8D44\u6E90\u5206\u914D\u3001\u5207\u6362\u9884\u6D4B\u3001\u4F18\u5316\u63A7\u5236\u7B49\u3002\\n\u6A21\u578B\u5E0C\u671B\u5B66\u5230\u4EC0\u4E48\u80FD\u529B\uFF1F\\n\u8BAD\u7EC3\u76EE\u6807\u662F\u63D0\u5347\u51C6\u786E\u7387\u3001\u964D\u4F4E\u635F\u5931\u3001\u4F18\u5316\u67D0\u4E2A\u901A\u4FE1\u6307\u6807\uFF0C\u8FD8\u662F\u517C\u987E\u591A\u4E2A\u76EE\u6807\uFF1F\\n\u5982\u679C\u6587\u7AE0\u6709\u76EE\u6807\u51FD\u6570\u3001\u4F18\u5316\u76EE\u6807\u3001\u7EA6\u675F\u6761\u4EF6\uFF0C\u8BF7\u89E3\u91CA\u5B83\u4EEC\u5206\u522B\u4EE3\u8868\u4EC0\u4E48\u3002\\n3. \u8BAD\u7EC3\u6570\u636E\u662F\u600E\u4E48\u6765\u7684\uFF1F\\n\\n\u8BF7\u5C3D\u53EF\u80FD\u8BE6\u7EC6\u5206\u6790\uFF1A\\n\\n\u6570\u636E\u6765\u81EA\u771F\u5B9E\u91C7\u96C6\u3001\u516C\u5F00\u6570\u636E\u96C6\u3001\u4EFF\u771F\u5E73\u53F0\uFF0C\u8FD8\u662F\u4F5C\u8005\u81EA\u5EFA\u6570\u636E\uFF1F\\n\u8F93\u5165\u6570\u636E\u5305\u542B\u54EA\u4E9B\u7279\u5F81\uFF1F\\n\u8F93\u51FA\u6807\u7B7E\u662F\u4EC0\u4E48\uFF1F\\n\u6570\u636E\u5728\u8BAD\u7EC3\u524D\u505A\u4E86\u54EA\u4E9B\u5904\u7406\uFF1F\\n\u4F8B\u5982\uFF1A\\n\u6570\u636E\u6E05\u6D17\\n\u7F3A\u5931\u503C\u5904\u7406\\n\u5F52\u4E00\u5316 / \u6807\u51C6\u5316\\n\u7F16\u7801\\n\u7279\u5F81\u63D0\u53D6\\n\u7279\u5F81\u9009\u62E9\\n\u6570\u636E\u589E\u5F3A\\n\u6ED1\u52A8\u7A97\u53E3\\n\u5E8F\u5217\u6784\u9020\\n\u6570\u636E\u96C6\u662F\u5982\u4F55\u5212\u5206\u7684\uFF1F\\n\u4F8B\u5982\u8BAD\u7EC3\u96C6\u3001\u9A8C\u8BC1\u96C6\u3001\u6D4B\u8BD5\u96C6\u6BD4\u4F8B\u3002\\n\u5982\u679C\u6587\u7AE0\u6CA1\u6709\u660E\u786E\u5199\u6E05\u695A\u6570\u636E\u5904\u7406\u6D41\u7A0B\uFF0C\u8BF7\u660E\u786E\u6307\u51FA\u7F3A\u5931\u5728\u54EA\u91CC\u3002\\n4. \u6A21\u578B\u7684\u8BAD\u7EC3\u6D41\u7A0B\u662F\u4EC0\u4E48\uFF1F\\n\\n\u8BF7\u628A\u8BAD\u7EC3\u8FC7\u7A0B\u6309\u6B65\u9AA4\u62C6\u5F00\u8BB2\uFF0C\u5C3D\u91CF\u50CF\u201C\u6D41\u7A0B\u56FE\u8BB2\u89E3\u201D\u4E00\u6837\u6E05\u695A\uFF0C\u4F8B\u5982\uFF1A\\n\\n\u7B2C\u4E00\u6B65\u8F93\u5165\u4EC0\u4E48\u6570\u636E\\n\u7B2C\u4E8C\u6B65\u505A\u4EC0\u4E48\u9884\u5904\u7406\\n\u7B2C\u4E09\u6B65\u9001\u5165\u4EC0\u4E48\u6A21\u578B\u7ED3\u6784\\n\u7B2C\u56DB\u6B65\u5982\u4F55\u8BA1\u7B97\u635F\u5931\\n\u7B2C\u4E94\u6B65\u5982\u4F55\u66F4\u65B0\u53C2\u6570\\n\u7B2C\u516D\u6B65\u4EC0\u4E48\u65F6\u5019\u505C\u6B62\u8BAD\u7EC3\\n\u7B2C\u4E03\u6B65\u5982\u4F55\u8BC4\u4F30\u8BAD\u7EC3\u7ED3\u679C\\n\\n\u8BF7\u5C3D\u91CF\u56DE\u7B54\u4EE5\u4E0B\u8BAD\u7EC3\u7EC6\u8282\uFF1A\\n\\n\u662F\u5426\u4ECE\u96F6\u5F00\u59CB\u8BAD\u7EC3\uFF1F\\n\u662F\u5426\u57FA\u4E8E\u9884\u8BAD\u7EC3\u6A21\u578B\u7EE7\u7EED\u8BAD\u7EC3\uFF1F\\n\u662F\u5426\u5206\u9636\u6BB5\u8BAD\u7EC3\uFF1F\\n\u662F\u5426\u5148\u9884\u8BAD\u7EC3\u518D\u5FAE\u8C03\uFF1F\\n\u662F\u5426\u591A\u4EFB\u52A1\u8054\u5408\u8BAD\u7EC3\uFF1F\\n\u662F\u5426\u5728\u7EBF\u8BAD\u7EC3 / \u79BB\u7EBF\u8BAD\u7EC3\uFF1F\\n\u662F\u5426\u96C6\u4E2D\u8BAD\u7EC3\u3001\u5206\u5E03\u5F0F\u8BAD\u7EC3\u3001\u8054\u90A6\u8BAD\u7EC3\uFF1F\\n\u662F\u5426\u6709\u6559\u5E08\u6A21\u578B / \u5B66\u751F\u6A21\u578B / \u84B8\u998F\u8FC7\u7A0B\uFF1F\\n5. \u6587\u7AE0\u7528\u4E86\u4EC0\u4E48\u635F\u5931\u51FD\u6570\u3001\u4F18\u5316\u65B9\u6CD5\u548C\u8BAD\u7EC3\u7B56\u7565\uFF1F\\n\\n\u8BF7\u91CD\u70B9\u89E3\u91CA\uFF1A\\n\\n\u635F\u5931\u51FD\u6570\u662F\u4EC0\u4E48\uFF1F\u4E3A\u4EC0\u4E48\u9009\u5B83\uFF1F\\n\u4F18\u5316\u5668\u662F\u4EC0\u4E48\uFF1F\\n\u4F8B\u5982 SGD\u3001Adam\u3001AdamW\u3001RMSProp \u7B49\u3002\\n\u5B66\u4E60\u7387\u6709\u6CA1\u6709\u7279\u522B\u8BBE\u8BA1\uFF1F\\n\u4F8B\u5982\u56FA\u5B9A\u5B66\u4E60\u7387\u3001\u5B66\u4E60\u7387\u8870\u51CF\u3001warm-up\u3002\\n\u662F\u5426\u7528\u4E86\u6B63\u5219\u5316\u65B9\u6CD5\uFF1F\\n\u4F8B\u5982 dropout\u3001weight decay\u3001early stopping\u3002\\n\u662F\u5426\u7528\u4E86 batch size\u3001epoch\u3001\u8FED\u4EE3\u8F6E\u6570\u7B49\u53C2\u6570\uFF1F\\n\u662F\u5426\u63D0\u5230\u4E86\u8D85\u53C2\u6570\u641C\u7D22\u6216\u8C03\u53C2\u65B9\u6CD5\uFF1F\\n\u662F\u5426\u7528\u4E86\u4EA4\u53C9\u9A8C\u8BC1\uFF1F\\n\u5982\u679C\u8FD9\u4E9B\u8BAD\u7EC3\u7EC6\u8282\u6CA1\u6709\u660E\u786E\u7ED9\u51FA\uFF0C\u8BF7\u660E\u786E\u8BF4\u660E\u201C\u6587\u7AE0\u672A\u8BE6\u7EC6\u4EA4\u4EE3\u201D\u3002\\n6. \u6A21\u578B\u7ED3\u6784\u548C\u8BAD\u7EC3\u8FC7\u7A0B\u4E4B\u95F4\u6709\u4EC0\u4E48\u5173\u7CFB\uFF1F\\n\\n\u8BF7\u89E3\u91CA\uFF1A\\n\\n\u6A21\u578B\u4E3A\u4EC0\u4E48\u8FD9\u6837\u8BBE\u8BA1\uFF0C\u662F\u5426\u662F\u4E3A\u4E86\u66F4\u5BB9\u6613\u8BAD\u7EC3\uFF0C\u8FD8\u662F\u4E3A\u4E86\u66F4\u597D\u63D0\u53D6\u7279\u5F81\uFF1F\\n\u6A21\u578B\u4E2D\u7684\u6BCF\u4E2A\u5173\u952E\u6A21\u5757\u5728\u8BAD\u7EC3\u4E2D\u8D77\u4EC0\u4E48\u4F5C\u7528\uFF1F\\n\u54EA\u4E9B\u6A21\u5757\u662F\u6838\u5FC3\u8BAD\u7EC3\u5BF9\u8C61\uFF1F\\n\u6709\u6CA1\u6709\u6A21\u5757\u662F\u56FA\u5B9A\u7684\uFF0C\u54EA\u4E9B\u662F\u53EF\u8BAD\u7EC3\u7684\uFF1F\\n\u5982\u679C\u6587\u7AE0\u6D89\u53CA\u6CE8\u610F\u529B\u673A\u5236\u3001\u7F16\u7801\u5668\u3001\u89E3\u7801\u5668\u3001\u7279\u5F81\u878D\u5408\u5C42\u3001\u51B3\u7B56\u5C42\u7B49\uFF0C\u8BF7\u8BF4\u660E\u5B83\u4EEC\u5728\u8BAD\u7EC3\u4E2D\u7684\u4F5C\u7528\u3002\\n7. \u6587\u4E2D\u662F\u5426\u6D89\u53CA\u5FAE\u8C03\uFF08fine-tuning\uFF09\uFF1F\\n\\n\u8BF7\u4ED4\u7EC6\u5224\u65AD\uFF1A\\n\\n\u8FD9\u662F\u5B8C\u6574\u8BAD\u7EC3\uFF0C\u8FD8\u662F\u5FAE\u8C03\u5DF2\u6709\u6A21\u578B\uFF1F\\n\u5982\u679C\u662F\u5FAE\u8C03\uFF0C\u5FAE\u8C03\u4E86\u54EA\u4E9B\u90E8\u5206\uFF1F\\n\u5C5E\u4E8E\u5168\u53C2\u6570\u5FAE\u8C03\u8FD8\u662F\u53C2\u6570\u9AD8\u6548\u5FAE\u8C03\uFF1F\\n\u5FAE\u8C03\u65F6\u4F7F\u7528\u4E86\u4EC0\u4E48\u6570\u636E\uFF1F\\n\u5FAE\u8C03\u7684\u76EE\u6807\u548C\u539F\u59CB\u8BAD\u7EC3\u76EE\u6807\u662F\u5426\u4E00\u6837\uFF1F\\n\u5FAE\u8C03\u540E\u4E3B\u8981\u63D0\u5347\u4E86\u4EC0\u4E48\u80FD\u529B\uFF1F\\n\u5982\u679C\u6587\u4E2D\u6CA1\u6709\u660E\u786E\u8BF4\u201Cfine-tuning\u201D\uFF0C\u4F46\u672C\u8D28\u662F\u5728\u5DF2\u6709\u6A21\u578B\u4E0A\u7EE7\u7EED\u9002\u914D\uFF0C\u4E5F\u8BF7\u6307\u51FA\u6765\u3002\\n8. \u5927\u6A21\u578B / \u5C0F\u6A21\u578B\u5728\u8BAD\u7EC3\u8FC7\u7A0B\u4E2D\u5206\u522B\u626E\u6F14\u4EC0\u4E48\u89D2\u8272\uFF1F\\n\\n\u8BF7\u5206\u6790\uFF1A\\n\\n\u6587\u7AE0\u91CC\u7684\u6A21\u578B\u66F4\u504F\u5927\u6A21\u578B\u8FD8\u662F\u5C0F\u6A21\u578B\uFF1F\\n\u4E3A\u4EC0\u4E48\uFF1F\\n\u8BAD\u7EC3\u8FC7\u7A0B\u662F\u5426\u9700\u8981\u5927\u91CF\u6570\u636E\u548C\u7B97\u529B\uFF1F\\n\u662F\u5426\u6709\u5927\u6A21\u578B\u84B8\u998F\u6210\u5C0F\u6A21\u578B\u3001\u538B\u7F29\u90E8\u7F72\u3001\u8FB9\u7F18\u90E8\u7F72\u7B49\u5185\u5BB9\uFF1F\\n\u662F\u5426\u4F53\u73B0\u51FA\u201C\u5927\u6A21\u578B\u8D1F\u8D23\u5B66\u4E60\u901A\u7528\u80FD\u529B\uFF0C\u5C0F\u6A21\u578B\u8D1F\u8D23\u8F7B\u91CF\u5316\u843D\u5730\u201D\u8FD9\u79CD\u601D\u8DEF\uFF1F\\n\u5982\u679C\u548C\u5927\u6A21\u578B/\u5C0F\u6A21\u578B\u5173\u7CFB\u4E0D\u5F3A\uFF0C\u4E5F\u8BF7\u660E\u786E\u8BF4\u660E\u3002\\n9. \u4F5C\u8005\u5982\u4F55\u8BC1\u660E\u8BAD\u7EC3\u662F\u6709\u6548\u7684\uFF1F\\n\\n\u8BF7\u4ECE\u8BAD\u7EC3\u89C6\u89D2\u56DE\u7B54\uFF1A\\n\\n\u7528\u4E86\u54EA\u4E9B\u8BC4\u4EF7\u6307\u6807\uFF1F\\n\u54EA\u4E9B\u5B9E\u9A8C\u6700\u80FD\u8BC1\u660E\u201C\u8BAD\u7EC3\u6709\u6548\u201D\uFF1F\\n\u662F\u5426\u5C55\u793A\u4E86\u8BAD\u7EC3\u524D\u540E\u5BF9\u6BD4\uFF1F\\n\u662F\u5426\u6709\u6536\u655B\u66F2\u7EBF\u3001\u635F\u5931\u53D8\u5316\u3001\u51C6\u786E\u7387\u53D8\u5316\uFF1F\\n\u662F\u5426\u505A\u4E86\u6D88\u878D\u5B9E\u9A8C\u6765\u8BC1\u660E\u67D0\u4E2A\u8BAD\u7EC3\u7B56\u7565\u6709\u6548\uFF1F\\n\u662F\u5426\u6BD4\u8F83\u4E86\u4E0D\u540C\u8BAD\u7EC3\u65B9\u5F0F\u3001\u4E0D\u540C\u8D85\u53C2\u6570\u3001\u4E0D\u540C\u6A21\u578B\u7ED3\u6784\uFF1F\\n10. \u4ECE\u201C\u8BAD\u7EC3\u8FC7\u7A0B\u662F\u5426\u5B8C\u6574\u3001\u662F\u5426\u79D1\u5B66\u201D\u7684\u89D2\u5EA6\u8BC4\u4EF7\u8FD9\u7BC7\u6587\u7AE0\\n\\n\u8BF7\u4F60\u5355\u72EC\u8BC4\u4EF7\uFF1A\\n\\n\u8FD9\u7BC7\u6587\u7AE0\u8BAD\u7EC3\u8FC7\u7A0B\u8BB2\u5F97\u6E05\u4E0D\u6E05\u695A\uFF1F\\n\u54EA\u4E9B\u8BAD\u7EC3\u7EC6\u8282\u4EA4\u4EE3\u5F97\u6BD4\u8F83\u5B8C\u6574\uFF1F\\n\u54EA\u4E9B\u5730\u65B9\u8BF4\u5F97\u4E0D\u591F\uFF0C\u5BFC\u81F4\u96BE\u4EE5\u590D\u73B0\uFF1F\\n\u8FD9\u7BC7\u6587\u7AE0\u66F4\u50CF\u201C\u771F\u6B63\u505A\u4E86\u624E\u5B9E\u8BAD\u7EC3\u7814\u7A76\u201D\uFF0C\u8FD8\u662F\u201C\u4E3B\u8981\u5C55\u793A\u65B9\u6CD5\u548C\u7ED3\u679C\uFF0C\u8BAD\u7EC3\u7EC6\u8282\u5199\u5F97\u8F83\u5C11\u201D\uFF1F\\n\u5982\u679C\u6211\u60F3\u590D\u73B0\u8FD9\u7BC7\u6587\u7AE0\uFF0C\u6700\u5927\u7684\u56F0\u96BE\u4F1A\u662F\u4EC0\u4E48\uFF1F","owner":"skywal303","upvotes":2,"downvotes":1,"upvoteDifference":1,"updatedAt":"2026-05-13T10:48:08.843Z"}')}}]);